private List<Pooled> pools(Basis basis) {
    List<SheetPool> all = basis.pools();
    List<SheetCrew> crewed = basis.crews();
    if (all.isEmpty() && crewed.isEmpty()) return List.of();
    BigDecimal pot = basis.pot();
